int main(){int checks=0;std::vector<std::uint8_t> p(5*5*4,255);for(unsigned y=1;y<4;++y)for(unsigned x=1;x<4;++x){auto i=(y*5+x)*4;p[i]=0;p[i+1]=0;p[i+2]=255;}auto original=p;auto mask=paf::backgroundMask(p,5,5,10);CHECK(mask[0]==255&&mask[12]==0);paf::backgroundRaster(p,5,5,2,10,4,0);CHECK(p[3]==0&&p[12*4+3]==255&&p[12*4+2]==255);paf::brushRaster(p,5,5,{{2.5,2.5}},1,0,paf::BrushKind::Eraser);CHECK(p[12*4+3]==0);paf::brushRaster(p,5,5,{{2.5,2.5}},1,0,paf::BrushKind::Restore,&original);CHECK(p[12*4+3]==255);p=original;paf::backgroundRaster(p,5,5,3,10,0,0x008000);CHECK(p[1]==128&&p[3]==255&&p[12*4+2]==255);p=original;paf::boxBlur(p,5,5,2);CHECK(p[12*4]>0&&p[12*4]<255);p={0,0,128,128,0,0,0,0};paf::Adjustments a;a.exposure=50;a.warmth=10;a.sharpness=20;paf::adjustRaster(p,2,1,a);CHECK(p[3]==128&&p[7]==0&&p[0]<=128&&p[2]<=128);p={0,0,255,255};a={};paf::adjustRaster(p,1,1,a);CHECK(p==std::vector<std::uint8_t>({0,0,255,255}));paf::brushRaster(p,1,1,{{.5,.5}},1,0x0000ff,paf::BrushKind::Pen);CHECK(p==std::vector<std::uint8_t>({255,0,0,255}));p=original;paf::straightenRaster(p,5,5,0);CHECK(p==original);paf::straightenRaster(p,5,5,15);CHECK(p[3]==255);paf::EditOptions e;e.width=10;e.height=5;unsigned w=5,h=5;paf::editBGRA(p,w,h,e);CHECK(w==10&&h==5);bool rejected=false;try{paf::brushRaster(p,10,5,{{0,0}},-1,0,paf::BrushKind::Pen);}catch(...){rejected=true;}CHECK(rejected);rejected=false;a.exposure=101;try{paf::adjustRaster(p,10,5,a);}catch(...){rejected=true;}CHECK(rejected);p=original;paf::brushRaster(p,5,5,{{2.5,2.5}},1,0xff0000,paf::BrushKind::Highlighter);CHECK(p[12*4+3]==255);p={128,128,128,128,0,0,0,0};paf::brushRaster(p,2,1,{{.5,.5}},1,0xff0000,paf::BrushKind::Highlighter);CHECK(p[3]>128&&p[0]<=p[3]&&p[2]<=p[3]);p.assign(7*7*4,255);p[(3*7+3)*4]=0;p[(3*7+3)*4+1]=0;p[(3*7+3)*4+2]=0;paf::brushRaster(p,7,7,{{3.5,3.5}},1,0,paf::BrushKind::Heal);CHECK(p[(3*7+3)*4]>200&&p[(3*7+3)*4+3]==255);p={40,40,40,255,80,80,80,255};paf::autoEnhanceRaster(p,2,1);CHECK(p[0]==0&&p[4]==255);p=original;paf::adjustRaster(p,5,5,paf::filterSettings(9));CHECK(p[12*4]==p[12*4+1]&&p[12*4+1]==p[12*4+2]);
 p.assign(17*3*4,255);for(unsigned y=0;y<3;++y)for(unsigned x=0;x<17;++x)for(unsigned c=0;c<3;++c)p[(y*17+x)*4+c]=std::uint8_t(255-std::min(x,16-x)*20);mask=paf::backgroundMask(p,17,3,0);CHECK(mask[17+8]==0&&mask[0]==255);
 std::cout<<checks<<" editor engine checks passed\n";}
